    if (!text || text.indexOf("\n") >= 0) return null;
    match = text.match(/^\/?#?\s*(\d{1,2})\s*(?:쫑|ㅉ)\s*$/);
    if (!match) match = compact.match(/^\/?#?(\d{1,2})(?:번|인)?(?:파티|구인)?(?:쫑|ㅉ|마감|종료)$/);
