      line = trim(lines[index]);
      if (!line) continue;
      match = line.match(/^(TOP|JUG|JGL|JG|JUNGLE|MID|ADC|AD|BOT|SUP|SPT|SUPPORT|탑|정글|미드|원딜|바텀|서폿|서포터)\s*[.:]\s*(.*)$/i);
